function recommendedTemplate(c){return c.estado==='nuevo'?'first':c.estado==='presentacion'?'presentation':c.tipo==='encuestado'&&Array.isArray(surveyFor(c)?.referidos)&&surveyFor(c).referidos.length?'thanks':'followup'}
