function nextActionFor(c){if(isOverdueContact(c))return {text:`Seguimiento vencido · ${formatDate(c.proximo_contacto)}`,due:true};if(isTodayContact(c))return {text:'Seguimiento programado para hoy',due:true};if(c.estado==='nuevo')return {text:`Primer contacto pendiente · ingresó ${formatAgo(c.created_at)}`,due:false};if(c.estado==='seguimiento'&&!c.proximo_contacto)return {text:'Falta programar el próximo contacto',due:true};if(c.estado==='presentacion')return {text:c.proximo_contacto?`Presentación · ${formatDate(c.proximo_contacto)}`:'Definir fecha de presentación',due:false};return {text:`Última actualización ${formatAgo(c.updated_at||c.created_at)}`,due:false}}
function activitiesFor(contactId){return (state.activities.get(contactId)||[]).slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))}
function addActivityLocal(activity){const list=state.activities.get(activity.contacto_id)||[];if(!list.some(row=>row.id===activity.id))list.unshift(activity);state.activities.set(activity.contacto_id,list);saveCache()}
